using IngSoft.Api.Entities;
using Microsoft.EntityFrameworkCore;

namespace IngSoft.Api.Data;

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Usuario> Usuarios => Set<Usuario>(); public DbSet<Cliente> Clientes => Set<Cliente>(); public DbSet<Producto> Productos => Set<Producto>(); public DbSet<Pedido> Pedidos => Set<Pedido>(); public DbSet<DetalleItem> DetallesItems => Set<DetalleItem>(); public DbSet<Cotizacion> Cotizaciones => Set<Cotizacion>(); public DbSet<OrdenCompra> OrdenesCompra => Set<OrdenCompra>(); public DbSet<Cobro> Cobros => Set<Cobro>(); public DbSet<Remito> Remitos => Set<Remito>(); public DbSet<Factura> Facturas => Set<Factura>(); public DbSet<DashboardResumen> DashboardResumen => Set<DashboardResumen>();
    protected override void OnModelCreating(ModelBuilder b)
    {
        b.Entity<Usuario>(e => { e.ToTable("Usuarios"); e.HasKey(x => x.IdUsuario); e.Property(x => x.IdUsuario).HasColumnName("id_usuario"); e.Property(x => x.Nombre).HasColumnName("nombre").HasMaxLength(100).IsRequired(); e.Property(x => x.Correo).HasColumnName("correo").HasMaxLength(150).IsRequired(); e.Property(x => x.Contrasena).HasColumnName("contrasena").HasMaxLength(100).IsRequired(); e.HasIndex(x => x.Correo).IsUnique(); });
        b.Entity<Cliente>(e => { e.ToTable("Clientes"); e.HasKey(x => x.IdCliente); e.Property(x => x.IdCliente).HasColumnName("id_cliente"); e.Property(x => x.RazonSocial).HasColumnName("razon_social").HasMaxLength(150).IsRequired(); e.Property(x => x.Cuit).HasColumnName("cuit").HasMaxLength(20).IsRequired(); e.Property(x => x.TipoCliente).HasColumnName("tipo_cliente").HasMaxLength(50).IsRequired(); e.Property(x => x.EstadoCredito).HasColumnName("estado_credito").HasMaxLength(50).IsRequired(); });
        b.Entity<Producto>(e => { e.ToTable("Productos"); e.HasKey(x => x.IdProducto); e.Property(x => x.IdProducto).HasColumnName("id_producto"); e.Property(x => x.Descripcion).HasColumnName("descripcion").HasMaxLength(200).IsRequired(); e.Property(x => x.PrecioMinorista).HasColumnName("precio_minorista").HasPrecision(18, 2); e.Property(x => x.StockActual).HasColumnName("stock_actual"); e.Property(x => x.StockMinimo).HasColumnName("stock_minimo"); });
        b.Entity<Pedido>(e => { e.ToTable("Pedidos"); e.HasKey(x => x.IdPedido); e.Property(x => x.IdPedido).HasColumnName("id_pedido"); e.Property(x => x.IdCliente).HasColumnName("id_cliente"); e.Property(x => x.FechaIngreso).HasColumnName("fecha_ingreso"); e.Property(x => x.Estado).HasColumnName("estado").HasMaxLength(50).IsRequired(); e.HasOne(x => x.Cliente).WithMany(x => x.Pedidos).HasForeignKey(x => x.IdCliente).OnDelete(DeleteBehavior.Restrict); });
        b.Entity<DetalleItem>(e => { e.ToTable("Detalles_Items"); e.HasKey(x => x.IdDetalle); e.Property(x => x.IdDetalle).HasColumnName("id_detalle"); e.Property(x => x.IdPedido).HasColumnName("id_pedido"); e.Property(x => x.IdProducto).HasColumnName("id_producto"); e.Property(x => x.Cantidad).HasColumnName("cantidad"); e.Property(x => x.PrecioUnitario).HasColumnName("precio_unitario").HasPrecision(18, 2); e.HasOne(x => x.Pedido).WithMany(x => x.Detalles).HasForeignKey(x => x.IdPedido); e.HasOne(x => x.Producto).WithMany(x => x.Detalles).HasForeignKey(x => x.IdProducto).OnDelete(DeleteBehavior.Restrict); });
        b.Entity<Cotizacion>(e => { e.ToTable("Cotizaciones"); e.HasKey(x => x.IdCotizacion); e.Property(x => x.IdCotizacion).HasColumnName("id_cotizacion"); e.Property(x => x.IdPedido).HasColumnName("id_pedido"); e.Property(x => x.FechaEmision).HasColumnName("fecha_emision"); e.Property(x => x.MontoTotal).HasColumnName("monto_total").HasPrecision(18, 2); e.Property(x => x.Estado).HasColumnName("estado").HasMaxLength(50).IsRequired(); e.HasOne(x => x.Pedido).WithMany(x => x.Cotizaciones).HasForeignKey(x => x.IdPedido); });
        b.Entity<OrdenCompra>(e => { e.ToTable("Ordenes_Compra"); e.HasKey(x => x.IdOc); e.Property(x => x.IdOc).HasColumnName("id_oc"); e.Property(x => x.IdCotizacion).HasColumnName("id_cotizacion"); e.Property(x => x.NroOcCliente).HasColumnName("nro_oc_cliente").HasMaxLength(50).IsRequired(); e.Property(x => x.FechaRecepcion).HasColumnName("fecha_recepcion"); e.Property(x => x.Estado).HasColumnName("estado").HasMaxLength(50).IsRequired(); e.Property(x => x.Pago).HasColumnName("pago").HasMaxLength(50).IsRequired(); e.HasOne(x => x.Cotizacion).WithMany(x => x.OrdenesCompra).HasForeignKey(x => x.IdCotizacion); });
        b.Entity<Cobro>(e => { e.ToTable("Cobros"); e.HasKey(x => x.IdCobro); e.Property(x => x.IdCobro).HasColumnName("id_cobro"); e.Property(x => x.IdOc).HasColumnName("id_oc"); e.Property(x => x.FechaRegistro).HasColumnName("fecha_registro"); e.Property(x => x.MedioPago).HasColumnName("medio_pago").HasMaxLength(50).IsRequired(); e.Property(x => x.Comprobante).HasColumnName("comprobante").HasMaxLength(260); e.Property(x => x.Estado).HasColumnName("estado").HasMaxLength(50).IsRequired(); e.HasIndex(x => x.IdOc).IsUnique(); e.HasOne(x => x.OrdenCompra).WithOne(x => x.Cobro).HasForeignKey<Cobro>(x => x.IdOc).OnDelete(DeleteBehavior.Restrict); });
        b.Entity<Remito>(e => { e.ToTable("Remitos"); e.HasKey(x => x.IdRemito); e.Property(x => x.IdRemito).HasColumnName("id_remito"); e.Property(x => x.IdOc).HasColumnName("id_oc"); e.Property(x => x.FechaEmision).HasColumnName("fecha_emision"); e.Property(x => x.EstadoEntrega).HasColumnName("estado_entrega").HasMaxLength(50).IsRequired(); e.Property(x => x.FirmaDigitalCliente).HasColumnName("firma_digital_cliente").HasColumnType("varbinary(max)"); e.HasIndex(x => x.IdOc).IsUnique(); e.HasOne(x => x.OrdenCompra).WithMany(x => x.Remitos).HasForeignKey(x => x.IdOc); });
        b.Entity<Factura>(e => { e.ToTable("Facturas"); e.HasKey(x => x.IdFactura); e.Property(x => x.IdFactura).HasColumnName("id_factura"); e.Property(x => x.IdRemito).HasColumnName("id_remito"); e.Property(x => x.NroFactura).HasColumnName("nro_factura").HasMaxLength(50).IsRequired(); e.Property(x => x.FechaEmision).HasColumnName("fecha_emision"); e.Property(x => x.Cae).HasColumnName("cae").HasMaxLength(50).IsRequired(); e.Property(x => x.MontoTotal).HasColumnName("monto_total").HasPrecision(18, 2); e.Property(x => x.Estado).HasColumnName("estado").HasMaxLength(50).IsRequired(); e.HasIndex(x => x.IdRemito).IsUnique(); e.HasOne(x => x.Remito).WithMany(x => x.Facturas).HasForeignKey(x => x.IdRemito); });
        b.Entity<DashboardResumen>(e => { e.HasNoKey(); e.ToView("vw_DashboardResumen"); e.Property(x => x.PedidosPendientes).HasColumnName("pedidosPendientes"); e.Property(x => x.Cotizaciones).HasColumnName("cotizaciones"); e.Property(x => x.OrdenesCompra).HasColumnName("ordenesCompra"); e.Property(x => x.PagosPendientes).HasColumnName("pagosPendientes"); e.Property(x => x.ListosParaRetirar).HasColumnName("listosParaRetirar"); e.Property(x => x.FacturasEmitidas).HasColumnName("facturasEmitidas"); });
    }
}
